import { APP_VERSION, DEMO_NOW, createDemoData, cloneData, priorityRank, addHours, dayISO } from './data.js';
import { loadState, saveState, clearState } from './storage.js';
import { scheduleAll, manualMove, applyPriority, computePlanningMetrics, validateBooking } from './planner.js';
import { kpis, calibrationStatus, calibrationAt, nextScheduledCalibration, resourceUtilisation, categoryMetrics, bottlenecks, skillsRisks, runDiagnostics, recomputeRequirementStatuses } from './diagnostics.js';

let state=null, route='dashboard', lastPlanDiagnostics=null;
const main=document.getElementById('main'), nav=document.getElementById('nav'), modal=document.getElementById('modal'), modalBody=document.getElementById('modalBody'), searchOverlay=document.getElementById('searchOverlay');
const fmtDate=(x,withTime=false)=>x?new Date(x).toLocaleString(undefined,withTime?{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}:{year:'numeric',month:'short',day:'numeric'}):'—';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const statusTone=s=>/Verified|Approved|Closed|Completed|Available|Valid|Pass|On Track|Ready/.test(s)?'green':/Failed|Expired|Breakdown|Overdue|Late/.test(s)?'red':/Blocked|At Risk|Due|Maintenance|Awaiting|Rework/.test(s)?'amber':/Planned|In Progress|Reserved|High/.test(s)?'blue':'grey';
const pill=s=>`<span class="pill ${statusTone(String(s))}">${esc(s)}</span>`;
const pct=(n,d)=>Math.round((n/Math.max(1,d))*100);

function addCompletedBookings(data){if(data.bookings?.some(b=>b.status==='Completed'))return;for(const l of data.legs.filter(x=>x.status==='Completed'&&x.actualStart&&x.actualEnd)){data.bookings.push({id:`BKG-${l.id}`,legId:l.id,programmeId:l.programmeId,methodId:l.methodId,start:l.actualStart,end:l.actualEnd,staffEnd:l.actualEnd,equipmentId:l.equipmentId,staffId:l.staffId,locked:true,status:'Completed',priority:data.programmes.find(p=>p.id===l.programmeId)?.priority||'Normal',dueDate:l.dueDate,lateHours:0});}}
async function init(){document.getElementById('versionText').textContent=`v${APP_VERSION}`;let loaded=await loadState();state=loaded?.meta?.version===APP_VERSION?loaded:createDemoData();addCompletedBookings(state);recomputeRequirementStatuses(state);if(!state.settings.lastPlannerRun){const r=scheduleAll(state,{recordAudit:false});state=r.data;lastPlanDiagnostics=r.diagnostics;}await saveState(state);bindGlobal();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});}
function bindGlobal(){nav.addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b)go(b.dataset.route)});document.querySelector('.brand').addEventListener('click',()=>go('dashboard'));document.getElementById('mobileNavBtn').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));document.getElementById('modalClose').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.getElementById('roleSelect').value=state.settings.role||'Lab Manager';document.getElementById('roleSelect').onchange=async e=>{state.settings.role=e.target.value;state.audit.push(audit('Role view changed','Demo UI','',e.target.value));await persist();const defaults={Technician:'execution','Test Engineer':'programmes',Planner:'planning','Lab Manager':'dashboard',Quality:'requirements'};go(defaults[e.target.value]||'dashboard');};const s=document.getElementById('globalSearch');s.oninput=()=>search(s.value);s.onkeydown=e=>{if(e.key==='Escape'){s.value='';searchOverlay.classList.add('hidden')}};document.getElementById('importFile').onchange=importJSON;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});}
function go(r){route=r;document.getElementById('sidebar').classList.remove('open');for(const b of nav.querySelectorAll('button'))b.classList.toggle('active',b.dataset.route===r);render();window.scrollTo({top:0});}
async function persist(){await saveState(state);}
function audit(action,entity,prev,next){return{timestamp:new Date().toISOString(),actor:state.settings.actor||'Demo Lab Manager',action,entity,previousValue:String(prev??''),newValue:String(next??'')}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.add('hidden'),3200)}
function openModal(html){modalBody.innerHTML=html;modal.classList.remove('hidden');modalBody.querySelector('input,select,button')?.focus();}
function closeModal(){modal.classList.add('hidden');modalBody.innerHTML=''}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function kpiCard(label,value,sub=''){return `<div class="card kpi-card"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`}
function section(title,body,hint=''){return `<section class="card"><div class="section-title"><h2>${title}</h2>${hint?`<span class="hint">${hint}</span>`:''}</div>${body}</section>`}
function render(){recomputeRequirementStatuses(state);const views={dashboard:renderDashboard,requirements:renderRequirements,programmes:renderProgrammes,planning:renderPlanning,execution:renderExecution,duts:renderDUTs,library:renderLibrary,equipment:renderEquipment,calibration:renderCalibration,people:renderPeople,analytics:renderAnalytics,admin:renderAdmin};main.innerHTML=(views[route]||renderDashboard)();wireRoute();}

function renderDashboard(){const vd=filteredDashboardData(),K=kpis(vd),bn=bottlenecks(vd),cats=categoryMetrics(vd).slice(0,7),riskCals=vd.equipment.map(e=>({e,s:calibrationStatus(e,vd)})).filter(x=>['red','amber'].includes(x.s.tone)).sort((a,b)=>(a.s.days??999)-(b.s.days??999)).slice(0,7);const role=state.settings.role||'Lab Manager';
 return pageHead('Laboratory Operations Dashboard',`Portfolio health, capacity, traceability and bottlenecks · ${role} view`,`<button class="btn primary" data-act="replan">↻ Recalculate Laboratory Plan</button>`)+dashboardFilterBar()+
 `<div class="grid kpi">${kpiCard('Active programmes',K.activeProgrammes,`${K.atRisk} at risk / blocked`)}${kpiCard('Open tests',K.testsOpen,`${K.inProgress} in progress · ${K.overdue} forecast late`)}${kpiCard('Requirements verified',`${K.reqVerified}%`,`${K.reqCoverage}% covered · ${K.reqFailed} failed`)}${kpiCard('Equipment utilisation',`${K.equipmentUtil}%`,'Next 4 weeks')}${kpiCard('Staff utilisation',`${K.staffUtil}%`,'Qualified attended workload')}${kpiCard('Development queue',K.devQueue,`${K.devHours} h engineering + technician demand`)}</div>`+
 `<div class="grid section-grid"><div class="grid">${section('Portfolio delivery',programmeRows(vd.programmes.slice().sort((a,b)=>priorityRank[b.priority]-priorityRank[a.priority]||new Date(a.dueDate)-new Date(b.dueDate)).slice(0,8),vd),'Forecast vs requested due date')}${section('Capacity by test category',cats.map(c=>`<div class="bar-row"><div class="bar-head"><strong>${esc(c.category)}</strong><span>${c.open} open · ${c.upcomingHours} h upcoming · ${c.late} late</span></div><div class="progress"><span style="width:${Math.max(3,c.utilisation)}%"></span></div></div>`).join(''))}</div><div class="grid">${section('Top bottlenecks',bn.map((b,i)=>`<div class="list-row"><div><strong>${i+1}. ${esc(b.name)}</strong><small>${esc(b.detail)}</small></div><span class="score">${b.score}</span></div>`).join(''),'Calculated from schedule and competency data')}${section('Calibration risk',riskCals.map(x=>`<div class="list-row"><div><strong class="link" data-entity="equipment" data-id="${x.e.id}">${x.e.id} · ${esc(x.e.name)}</strong><small>Due ${fmtDate(x.e.calibrationDue)} · ${esc(x.e.location)}</small></div><span class="pill ${x.s.tone}">${x.s.label}</span></div>`).join('')||'<div class="empty">No upcoming calibration risk.</div>')}</div></div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Requirement health',reqHealth(vd))}${section('New-test development',devRows(vd))}</div>`;}
function dashboardFilterBar(){const f=state.settings.dashboardFilters||{};const customers=[...new Set(state.programmes.map(p=>p.customer))].sort(),cats=[...new Set(state.methods.map(m=>m.category))].sort();return `<div class="filters"><select id="dashProgramme"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}" ${f.programme===p.id?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select><select id="dashCustomer"><option value="">All customers</option>${customers.map(x=>`<option ${f.customer===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="dashCategory"><option value="">All test categories</option>${cats.map(x=>`<option ${f.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="dashPriority"><option value="">All priorities</option>${['Critical','High','Normal','Low'].map(x=>`<option ${f.priority===x?'selected':''}>${x}</option>`).join('')}</select><select id="dashStatus"><option value="">All risk states</option>${['On Track','At Risk','Late','Blocked'].map(x=>`<option ${f.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="dashEquipment"><option value="">All equipment</option>${state.equipment.map(e=>`<option value="${e.id}" ${f.equipment===e.id?'selected':''}>${e.id}</option>`).join('')}</select><select id="dashStaff"><option value="">All staff</option>${state.staff.map(x=>`<option value="${x.id}" ${f.staff===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`}
function filteredDashboardData(){const f=state.settings.dashboardFilters||{};let programs=state.programmes.filter(p=>(!f.programme||p.id===f.programme)&&(!f.customer||p.customer===f.customer)&&(!f.priority||p.priority===f.priority)&&(!f.status||p.scheduleRisk===f.status));const pids=new Set(programs.map(p=>p.id));let methods=state.methods.filter(m=>!f.category||m.category===f.category),mids=new Set(methods.map(m=>m.id));let legs=state.legs.filter(l=>pids.has(l.programmeId)&&mids.has(l.methodId)&&(!f.equipment||l.equipmentId===f.equipment)&&(!f.staff||l.staffId===f.staff));const legIds=new Set(legs.map(l=>l.id));if(f.category||f.equipment||f.staff){const usedPids=new Set(legs.map(l=>l.programmeId));programs=programs.filter(p=>usedPids.has(p.id));}const finalPids=new Set(programs.map(p=>p.id));const requirements=state.requirements.filter(r=>finalPids.has(r.programmeId));const bookings=state.bookings.filter(b=>legIds.has(b.legId));const equipment=f.equipment?state.equipment.filter(e=>e.id===f.equipment):state.equipment;const staff=f.staff?state.staff.filter(s=>s.id===f.staff):state.staff;return {...state,programmes:programs,requirements,methods,legs,duts:state.duts.filter(d=>finalPids.has(d.programmeId)),bookings,equipment,staff,devTasks:state.devTasks.filter(d=>finalPids.has(d.programmeId))};}
function programmeRows(programmes,data=state){return `<div class="table-wrap"><table><thead><tr><th>Programme</th><th>Project</th><th>Priority</th><th>Due</th><th>Forecast</th><th>Risk</th><th>Progress</th></tr></thead><tbody>${programmes.map(p=>{const ls=data.legs.filter(l=>l.programmeId===p.id),done=ls.filter(l=>l.status==='Completed').length;return `<tr><td><span class="link mono" data-entity="programme" data-id="${p.id}">${p.id}</span></td><td><strong>${esc(p.project)}</strong><div class="muted small">${esc(p.product)}</div></td><td>${pill(p.priority)}</td><td>${fmtDate(p.dueDate)}</td><td>${fmtDate(p.forecastCompletion)}</td><td>${pill(p.scheduleRisk||'Unplanned')}</td><td><div class="bar-head"><span>${done}/${ls.length}</span><span>${pct(done,ls.length)}%</span></div><div class="progress"><span style="width:${pct(done,ls.length)}%"></span></div></td></tr>`}).join('')}</tbody></table></div>`}
function reqHealth(data=state){const sts=['Verified','Partially Verified','Planned','Blocked','Failed','Not Covered'];return `<div class="list">${sts.map(s=>{const n=data.requirements.filter(r=>r.status===s).length;return `<div class="bar-row"><div class="bar-head"><strong>${s}</strong><span>${n} · ${pct(n,data.requirements.length)}%</span></div><div class="progress"><span style="width:${pct(n,data.requirements.length)}%"></span></div></div>`}).join('')}</div>`}
function devRows(data=state){return `<div class="list">${data.devTasks.slice(0,6).map(d=>`<div class="list-row"><div><strong>${d.id} · ${esc(d.name)}</strong><small>${esc(data.programmes.find(p=>p.id===d.programmeId)?.project)} · ${d.estimatedEngineeringHours}h engineering · due ${fmtDate(d.dueDate)}</small></div>${pill(d.completeDate?'Complete':d.status)}</div>`).join('')}</div>`}

function renderRequirements(){const opts=[...new Set(state.requirements.map(r=>r.status))].sort();return pageHead('Requirement Flowdown','Source requirement → validation requirement → test demand → execution evidence',`<button class="btn" data-act="export-req-csv">⇩ Requirements CSV</button>`)+
 `<div class="filters"><select id="reqStatus"><option value="">All status</option>${opts.map(x=>`<option>${x}</option>`).join('')}</select><select id="reqCrit"><option value="">All criticality</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select><input id="reqFilter" placeholder="Filter ID, text, programme…"></div><div id="reqKpis" class="grid kpi"></div><section class="card"><div class="section-title"><h2>Requirement Traceability Matrix</h2><span class="hint">Click a requirement for end-to-end flowdown</span></div><div class="table-wrap"><table><thead><tr><th>Requirement</th><th>Source</th><th>Programme</th><th>Criticality</th><th>Verification</th><th>Test / Leg</th><th>DUT Coverage</th><th>Status</th><th>Evidence</th></tr></thead><tbody id="reqBody"></tbody></table></div></section>`;}
function renderReqTable(){const f=(document.getElementById('reqFilter')?.value||'').toLowerCase(),st=document.getElementById('reqStatus')?.value||'',cr=document.getElementById('reqCrit')?.value||'';const rows=state.requirements.filter(r=>(!st||r.status===st)&&(!cr||r.criticality===cr)&&(!f||`${r.id} ${r.sourceId} ${r.text} ${r.programmeId}`.toLowerCase().includes(f)));const covered=rows.filter(r=>r.status!=='Not Covered').length,ver=rows.filter(r=>r.status==='Verified').length,fail=rows.filter(r=>r.status==='Failed').length;document.getElementById('reqKpis').innerHTML=kpiCard('Shown',rows.length,`${covered} covered`)+kpiCard('Coverage',`${pct(covered,rows.length)}%`,'Mapped to one or more test legs')+kpiCard('Verified',`${pct(ver,rows.length)}%`,`${ver} requirements`)+kpiCard('Failed',fail,'Derived from test results')+kpiCard('Not planned',rows.filter(r=>r.status==='Not Covered').length,'No test coverage')+kpiCard('Critical outstanding',rows.filter(r=>r.criticality==='Critical'&&r.status!=='Verified').length,'Management attention');document.getElementById('reqBody').innerHTML=rows.map(r=>{const p=state.programmes.find(p=>p.id===r.programmeId),ls=state.legs.filter(l=>l.requirementIds.includes(r.id));const dutCount=new Set(ls.flatMap(l=>l.dutIds)).size,ev=state.results.filter(x=>ls.some(l=>l.id===x.legId)).length;return `<tr><td><span class="link mono" data-entity="requirement" data-id="${r.id}">${r.id}</span><div class="small muted">${esc(r.text).slice(0,80)}${r.text.length>80?'…':''}</div></td><td class="mono">${r.sourceId}</td><td>${p?.id}<div class="muted small">${esc(p?.project)}</div></td><td>${pill(r.criticality)}</td><td>${r.verificationMethod}</td><td>${ls.map(l=>`<span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span>`).join(', ')||'—'}</td><td>${dutCount} DUTs</td><td>${pill(r.status)}</td><td>${ev?`${ev} result records`:'—'}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">No requirements match the filters.</td></tr>';wireEntities(document.getElementById('reqBody'));}

function renderProgrammes(){return pageHead('Validation Programmes','Prioritise programmes and inspect flowdown, DUT populations, schedule risk and completion',`<button class="btn primary" data-act="replan">↻ Recalculate Laboratory Plan</button>`)+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Programme</th><th>Customer / Product</th><th>Owner</th><th>Priority</th><th>Business score</th><th>Due</th><th>Forecast</th><th>Risk</th><th>Progress</th></tr></thead><tbody>${state.programmes.map(p=>{const ls=state.legs.filter(l=>l.programmeId===p.id),done=ls.filter(l=>l.status==='Completed').length;return `<tr><td><span class="link mono" data-entity="programme" data-id="${p.id}">${p.id}</span><div><strong>${esc(p.project)}</strong></div><div class="small muted">${esc(p.storyline)}</div></td><td>${esc(p.customer)}<div class="small muted">${esc(p.product)} · ${p.productRevision}</div></td><td>${esc(p.owner)}</td><td><select class="priority-change" data-id="${p.id}">${['Critical','High','Normal','Low'].map(x=>`<option ${x===p.priority?'selected':''}>${x}</option>`).join('')}</select></td><td>${p.businessPriority}</td><td>${fmtDate(p.dueDate)}</td><td>${fmtDate(p.forecastCompletion)}</td><td>${pill(p.scheduleRisk||p.status)}</td><td>${done}/${ls.length}<div class="progress"><span style="width:${pct(done,ls.length)}%"></span></div></td></tr>`}).join('')}</tbody></table></div></section>`}

function renderPlanning(){const m=computePlanningMetrics(state);return pageHead('Test Planning','Deterministic resource-constrained schedule · equipment, staff, calibration, dependencies and priority',`<button class="btn" data-act="scenario">◈ What-if Scenario</button><button class="btn primary" data-act="replan">↻ Recalculate Schedule</button>`)+
 `<div class="planning-summary"><span class="metric-chip"><b>${m.planned}</b> scheduled</span><span class="metric-chip"><b>${m.unscheduled}</b> unscheduled</span><span class="metric-chip"><b>${m.late}</b> late bookings</span><span class="metric-chip"><b>${m.atRisk}</b> programmes at risk</span>${state.settings.scenario?`<span class="metric-chip">Scenario active: <b>${esc(state.settings.scenario.label||state.settings.scenario.type)}</b> <button class="btn small" data-act="reset-scenario">Reset</button></span>`:''}</div>`+
 section('Equipment timeline · next 14 days',planningTimeline(),'Click a booking to inspect or manually lock/move it')+
 `<div style="margin-top:14px">${section('Staff planning view',planningStaffRows(),'Qualified attended bookings in the next 14 days')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Unscheduled / blocked demand',unscheduledRows())}${section('Last replanning impact',planMoveRows())}</div>`;}
function planningTimeline(){const days=Array.from({length:14},(_,i)=>new Date(DEMO_NOW.getTime()+i*86400000));const eqRows=state.equipment.filter(e=>state.bookings.some(b=>b.equipmentId===e.id)||state.maintenance.some(m=>m.equipmentId===e.id)).slice(0,18);const header=`<div class="gantt-head"><div>Equipment</div>${days.map(d=>`<div>${d.toLocaleDateString(undefined,{weekday:'short',day:'numeric'})}</div>`).join('')}</div>`;const rows=eqRows.map(eq=>{const blocks=[];for(const b of state.bookings.filter(x=>x.equipmentId===eq.id)){const a=(new Date(b.start)-DEMO_NOW)/86400000,z=(new Date(b.end)-new Date(b.start))/86400000;if(a<14&&a+z>0)blocks.push(`<div class="booking ${b.lateHours>0?'late':''} ${b.locked?'locked':''}" data-booking="${b.id}" style="left:calc(180px + ${Math.max(0,a)} * ((100% - 180px)/14));width:calc(${Math.max(.08,Math.min(14-a,z))} * ((100% - 180px)/14))" title="${b.id}">${b.legId} · ${b.programmeId}</div>`)}for(const x of state.maintenance.filter(m=>m.equipmentId===eq.id)){const a=(new Date(x.start)-DEMO_NOW)/86400000,z=(new Date(x.end)-new Date(x.start))/86400000;if(a<14&&a+z>0)blocks.push(`<div class="booking maint" style="left:calc(180px + ${Math.max(0,a)} * ((100% - 180px)/14));width:calc(${Math.max(.08,Math.min(14-a,z))} * ((100% - 180px)/14))">${esc(x.type)}</div>`)}return `<div class="gantt-row"><div class="gantt-label"><span class="link" data-entity="equipment" data-id="${eq.id}">${eq.id}</span>&nbsp;${esc(eq.name)}</div>${days.map(()=>'<div class="gantt-cell"></div>').join('')}${blocks.join('')}</div>`}).join('');return `<div class="timeline-legend" style="padding:9px 14px"><span><i class="legend-box"></i> planned</span><span><i class="legend-box late"></i> late</span><span><i class="legend-box maint"></i> maintenance / outage</span><span>▣ outline = locked</span></div><div class="gantt-shell"><div class="gantt">${header}${rows}</div></div>`}
function planningStaffRows(){const end=new Date(DEMO_NOW.getTime()+14*86400000),rows=state.staff.map(s=>{const bs=state.bookings.filter(b=>b.staffId===s.id&&new Date(b.start)<end&&new Date(b.staffEnd||b.end)>DEMO_NOW).sort((a,b)=>new Date(a.start)-new Date(b.start));const hours=bs.reduce((sum,b)=>sum+(new Date(b.staffEnd||b.end)-new Date(b.start))/3600000,0);return {s,bs,hours}}).filter(x=>x.bs.length).sort((a,b)=>b.hours-a.hours);return `<div class="table-wrap"><table><thead><tr><th>Staff</th><th>Role</th><th>Booked attended hours</th><th>Upcoming allocations</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="link" data-entity="staff" data-id="${x.s.id}">${esc(x.s.name)}</span></td><td>${esc(x.s.role)}</td><td>${x.hours.toFixed(1)}h</td><td>${x.bs.map(b=>`${b.legId} · ${fmtDate(b.start,true)}`).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`}
function unscheduledRows(){const ls=state.legs.filter(l=>l.status!=='Completed'&&!l.plannedStart);return `<div class="list">${ls.slice(0,12).map(l=>`<div class="list-row"><div><strong><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span> · ${esc(l.name)}</strong><small>${l.programmeId} · due ${fmtDate(l.dueDate)} · ${esc(l.blockingReason||'Awaiting feasible slot')}</small></div>${pill(l.status)}</div>`).join('')||'<div class="empty">All active test demand is scheduled.</div>'}</div>`}
function planMoveRows(){const moved=lastPlanDiagnostics?.moved||[];return `<div class="list">${moved.slice(0,10).map(x=>`<div class="list-row"><div><strong>${x.legId}</strong><small>${fmtDate(x.oldStart,true)} → ${fmtDate(x.newStart,true)} · ${x.oldEquipment||'—'} → ${x.newEquipment||'—'}</small></div>${pill('Rescheduled')}</div>`).join('')||'<div class="empty">No schedule moves recorded in the latest recalculation.</div>'}</div>`}

function renderExecution(){const legs=state.legs.slice().sort((a,b)=>{const order={"In Progress":0,"At Risk":1,"Planned":2,"Blocked":3,"Completed":4,"Draft":5};return (order[a.status]??9)-(order[b.status]??9)});return pageHead('Test Execution','Lifecycle control, readiness checks, results and deterministic acceptance evaluation')+
 `<div class="grid kpi">${kpiCard('In progress',legs.filter(l=>l.status==='In Progress').length,'Active executions')}${kpiCard('Ready / planned',legs.filter(l=>['Ready','Planned'].includes(l.status)).length,'Awaiting start')}${kpiCard('Blocked',legs.filter(l=>l.blockingReason).length,'Constraint or prerequisite')}${kpiCard('Completed',legs.filter(l=>l.status==='Completed').length,'Evidence captured')}${kpiCard('Failed DUTs',state.duts.filter(d=>d.status==='Failed').length,'Derived from results')}${kpiCard('Awaiting review',legs.filter(l=>l.status==='Awaiting Review').length,'Quality review queue')}</div>`+
 `<section class="card"><div class="table-wrap"><table><thead><tr><th>Leg</th><th>Programme</th><th>Method</th><th>DUTs</th><th>Planned</th><th>Resources</th><th>Status</th><th>Blocking / Evidence</th><th>Action</th></tr></thead><tbody>${legs.map(l=>{const m=state.methods.find(x=>x.id===l.methodId),res=state.results.filter(r=>r.legId===l.id);return `<tr><td><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span><div class="muted small">${esc(l.name)}</div></td><td>${l.programmeId}</td><td>${m?.id} Rev ${m?.revision}</td><td>${l.dutIds.length}</td><td>${fmtDate(l.plannedStart,true)}<div class="muted small">→ ${fmtDate(l.plannedEnd,true)}</div></td><td>${l.equipmentId||'—'}<div class="muted small">${state.staff.find(s=>s.id===l.staffId)?.name||'—'}</div></td><td>${pill(l.status)}</td><td><span class="small">${esc(l.blockingReason||`${res.length} result records`)}</span></td><td>${l.status==='In Progress'?`<button class="btn small primary" data-act="record-result" data-id="${l.id}">Results</button>`:`<button class="btn small" data-act="readiness" data-id="${l.id}">Check</button>`}</td></tr>`}).join('')}</tbody></table></div></section>`}

function renderDUTs(){return pageHead('DUTs & Specimens','Genealogy, programme allocation, failed/removed units and complete test journey')+`<div class="filters"><select id="dutProg"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select><select id="dutStatus"><option value="">All status</option><option>Available</option><option>Failed</option><option>Removed</option></select><input id="dutFilter" placeholder="Serial number or DUT ID"></div><section class="card"><div class="table-wrap"><table><thead><tr><th>DUT</th><th>Serial</th><th>Product</th><th>Programme</th><th>Group</th><th>Status</th><th>Legs assigned</th><th>Results</th></tr></thead><tbody id="dutBody"></tbody></table></div></section>`}
function renderDutTable(){const pr=document.getElementById('dutProg')?.value||'',st=document.getElementById('dutStatus')?.value||'',f=(document.getElementById('dutFilter')?.value||'').toLowerCase();const rows=state.duts.filter(d=>(!pr||d.programmeId===pr)&&(!st||d.status===st)&&(!f||`${d.id} ${d.serialNumber}`.toLowerCase().includes(f)));document.getElementById('dutBody').innerHTML=rows.map(d=>{const ls=state.legs.filter(l=>l.dutIds.includes(d.id)),rs=state.results.filter(r=>r.dutId===d.id);return `<tr><td><span class="link mono" data-entity="dut" data-id="${d.id}">${d.id}</span></td><td>${d.serialNumber}</td><td>${esc(d.product)}</td><td>${d.programmeId}</td><td>${d.group}</td><td>${pill(d.status)}</td><td>${ls.length}</td><td>${rs.length} · ${rs.some(r=>r.status==='FAIL')?pill('FAIL'):rs.length?pill('PASS'):'—'}</td></tr>`}).join('');wireEntities(document.getElementById('dutBody'));}

function renderLibrary(){const methods=state.methods;return pageHead('Test Library','Reusable released test methods with resource requirements, standard durations and performance analytics',`<button class="btn primary" data-act="request-new-test">＋ Request New Test</button>`)+`<div class="grid kpi">${kpiCard('Active methods',methods.filter(m=>m.active).length,'Across '+new Set(methods.map(m=>m.category)).size+' categories')}${kpiCard('Standard execution',state.legs.filter(l=>!l.developmentTaskId).length,'Legs using released methods')}${kpiCard('Development-linked',state.legs.filter(l=>l.developmentTaskId).length,'Validation legs gated by method development')}${kpiCard('Avg actual variance',`${Math.round(methods.reduce((s,m)=>s+(m.avgActualFactor-1),0)/methods.length*100)}%`,'Actual vs library standard')}${kpiCard('Unattended methods',methods.filter(m=>m.unattended).length,'Equipment continues without full-time staffing')}${kpiCard('Obsolete',methods.filter(m=>!m.active).length,'Excluded from new plans')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Method</th><th>Category</th><th>Rev</th><th>Standard duration</th><th>Required resource</th><th>Skill</th><th>DUT capacity</th><th>Staffing</th><th>Uses</th><th>Actual vs std</th></tr></thead><tbody>${methods.map(m=>`<tr><td><span class="link mono" data-entity="method" data-id="${m.id}">${m.id}</span><div><strong>${esc(m.name)}</strong></div></td><td>${m.category}</td><td>${m.revision}</td><td>${m.setupHours+m.executionHours+m.teardownHours+m.analysisHours}h<div class="muted small">setup ${m.setupHours} · run ${m.executionHours} · teardown ${m.teardownHours} · analysis ${m.analysisHours}</div></td><td>${m.equipmentType}</td><td>${m.requiredSkills.join(', ')}</td><td>${m.dutCapacity}</td><td>${m.unattended?'Unattended capable':'Continuous / attended'}</td><td>${m.useCount}</td><td>${Math.round(m.avgActualFactor*100)}%</td></tr>`).join('')}</tbody></table></div></section>`}

function renderEquipment(){const u=resourceUtilisation(state),map=Object.fromEntries(u.equipment.map(x=>[x.id,x]));return pageHead('Equipment Register','Capability, utilisation, calibration, maintenance and planning availability',`<button class="btn" data-act="export-equipment-csv">⇩ Equipment CSV</button>`)+`<div class="grid kpi">${kpiCard('Assets',state.equipment.length,'Registered laboratory equipment')}${kpiCard('Available',state.equipment.filter(e=>e.status==='Available').length,'Current asset status')}${kpiCard('Maintenance',state.equipment.filter(e=>e.status==='Maintenance').length,'Unavailable by status')}${kpiCard('Breakdown',state.equipment.filter(e=>e.status==='Breakdown').length,'Corrective maintenance')}${kpiCard('Calibration risk',state.equipment.filter(e=>['red','amber'].includes(calibrationStatus(e,state).tone)).length,'Expired or due ≤60d')}${kpiCard('Portfolio utilisation',`${u.equipmentAvg}%`,'Next 4 weeks')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Type / Capability</th><th>Manufacturer</th><th>Location</th><th>Status</th><th>Capacity</th><th>Utilisation</th><th>Calibration</th><th>Maintenance</th></tr></thead><tbody>${state.equipment.map(e=>{const c=calibrationStatus(e,state),ut=map[e.id]?.pct||0;return `<tr><td><span class="link mono" data-entity="equipment" data-id="${e.id}">${e.id}</span><div class="muted small">${e.assetNumber} · ${e.serialNumber}</div></td><td><strong>${esc(e.name)}</strong><div class="muted small">${esc(e.capability)}</div></td><td>${e.manufacturer}<div class="muted small">${e.model}</div></td><td>${e.location}</td><td>${pill(e.status)}</td><td>${e.capacity}</td><td><div class="bar-head"><span>${ut}%</span></div><div class="heat"><span style="width:${ut}%"></span></div></td><td><span class="pill ${c.tone}">${c.label}</span><div class="muted small">${fmtDate(e.calibrationDue)}</div></td><td>${fmtDate(e.maintenanceDate)}</td></tr>`}).join('')}</tbody></table></div></section>`}

function renderCalibration(){const current=state.equipment.filter(e=>e.calibrationRequired).map(e=>{const s=calibrationStatus(e,state),c=s.calibration,next=nextScheduledCalibration(state,e.id);return{e,c,next,s}}).sort((a,b)=>(a.s.days??999)-(b.s.days??999));const affected=state.bookings.filter(b=>{const e=state.equipment.find(x=>x.id===b.equipmentId);if(!e?.calibrationRequired)return false;const c=calibrationAt(state,e.id,b.start,{allowScheduled:true});return !c||new Date(c.dueDate)<new Date(b.end)}).length;return pageHead('Calibration Management','Validity, warning horizons, certificates and planning impact',`<button class="btn" data-act="add-calibration">＋ Add Calibration</button><button class="btn" data-act="export-cal-csv">⇩ CSV</button>`)+`<div class="grid kpi">${kpiCard('Valid',current.filter(x=>x.s.tone==='green').length,'Beyond 60-day warning')}${kpiCard('Due ≤60d',current.filter(x=>x.s.tone==='amber').length,'Amber warning')}${kpiCard('Expired / ≤7d',current.filter(x=>x.s.tone==='red').length,'Planning blocker / urgent')}${kpiCard('Calibration records',state.calibrations.length,'Current, historical + scheduled')}${kpiCard('Future tests affected',affected,'Effective calibration checked at planned use')}${kpiCard('Warning thresholds',state.settings.calibrationWarningDays.join(' / ')+'d','Configurable in Administration')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Equipment</th><th>Current calibration</th><th>Date</th><th>Due</th><th>Status</th><th>Next planned</th><th>Provider</th><th>Certificate</th><th>As found / left</th></tr></thead><tbody>${current.map(x=>`<tr><td><span class="link mono" data-entity="equipment" data-id="${x.e.id}">${x.e.id}</span><div>${esc(x.e.name)}</div></td><td class="mono">${x.c?.id||'—'}</td><td>${fmtDate(x.c?.calibrationDate)}</td><td>${fmtDate(x.c?.dueDate)}</td><td><span class="pill ${x.s.tone}">${x.s.label}</span></td><td>${x.next?`<span class="pill blue">Scheduled</span><div class="muted small">${fmtDate(x.next.calibrationDate,true)} · ${esc(x.next.id)}</div>`:'—'}</td><td>${esc(x.c?.provider||'—')}</td><td>${x.c?`<a class="link" href="${esc(x.c.certificatePath)}" target="_blank" rel="noopener">${esc(x.c.certificateNumber)}</a>`:'—'}</td><td>${esc(x.c?.asFound||'—')} / ${esc(x.c?.asLeft||'—')}</td></tr>`).join('')}</tbody></table></div></section>`}

function renderPeople(){const u=resourceUtilisation(state),um=Object.fromEntries(u.staff.map(x=>[x.id,x])),risks=skillsRisks(state);return pageHead('People & Skills','Competency, authorisation, availability, workload and single-point qualification risks')+`<div class="grid kpi">${kpiCard('Staff',state.staff.length,'Technicians, engineers, specialists, manager')}${kpiCard('Staff utilisation',`${u.staffAvg}%`,'Attended planning load')}${kpiCard('Single-point skills',risks.filter(r=>r.count===1).length,'Only one independent operator')}${kpiCard('Qualification gaps',risks.filter(r=>r.count===0).length,'No independent coverage')}${kpiCard('Methods covered',`${pct(state.methods.length-risks.filter(r=>r.count===0).length,state.methods.length)}%`,'At least one independent qualification')}${kpiCard('People unavailable',state.staff.filter(s=>s.availability.some(a=>new Date(a.end)>DEMO_NOW)).length,'Future leave / training blocks')}</div><div class="grid section-grid"><section class="card"><div class="section-title"><h2>Staff workload</h2></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Role / Team</th><th>Skills</th><th>Qualifications</th><th>Availability</th><th>Workload</th></tr></thead><tbody>${state.staff.map(s=>{const ut=um[s.id]?.pct||0;return `<tr><td><span class="link" data-entity="staff" data-id="${s.id}">${esc(s.name)}</span><div class="mono small muted">${s.id}</div></td><td>${esc(s.role)}<div class="muted small">${esc(s.team)}</div></td><td>${s.skills.join(', ')}</td><td>${s.qualifications.length}<div class="muted small">${s.proficiency}</div></td><td>${s.availability.map(a=>`${fmtDate(a.start)}–${fmtDate(a.end)} ${a.reason}`).join('<br>')||'Available'}</td><td>${ut}%<div class="heat"><span style="width:${ut}%"></span></div></td></tr>`}).join('')}</tbody></table></div></section>${section('Single-point competency risks',risks.slice(0,15).map(r=>`<div class="list-row"><div><strong>${r.methodId} · ${esc(r.name)}</strong><small>${r.count?esc(r.people):'No independent qualified person'}</small></div><span class="pill ${r.count===0?'red':'amber'}">${r.count} qualified</span></div>`).join('')||'<div class="empty">No coverage risks.</div>','Independent / Reviewer / Expert levels')}</div>`}

function renderAnalytics(){const K=kpis(state),cats=categoryMetrics(state),u=resourceUtilisation(state),u8=resourceUtilisation(state,56),u12=resourceUtilisation(state,84),completed=state.legs.filter(l=>l.actualStart&&l.actualEnd).map(l=>{const m=state.methods.find(x=>x.id===l.methodId),actual=(new Date(l.actualEnd)-new Date(l.actualStart))/3600000,std=m?m.setupHours+m.executionHours+m.teardownHours+m.analysisHours:0;return{l,m,actual,std,delta:actual-std}});return pageHead('Reports / Analytics','Planned vs actual, category demand, utilisation, throughput and test development economics',`<button class="btn" data-act="export-plan-csv">⇩ Test Plan CSV</button><button class="btn" data-act="export-kpi-csv">⇩ KPI CSV</button>`)+`<div class="planning-summary"><span class="metric-chip"><b>${u.equipmentAvg}%</b> equipment capacity · 4 weeks</span><span class="metric-chip"><b>${u8.equipmentAvg}%</b> · 8 weeks</span><span class="metric-chip"><b>${u12.equipmentAvg}%</b> · 12 weeks</span><span class="metric-chip"><b>${state.legs.filter(l=>!l.plannedStart&&l.status!=='Completed').length}</b> unallocated demand</span></div><div class="grid kpi">${kpiCard('On-time forecast',`${K.onTimePct}%`,'Programme forecast completion')}${kpiCard('Avg turnaround',`${K.avgTurnaround}h`,'Completed legs')}${kpiCard('Median turnaround',`${K.medianTurnaround}h`,'Completed legs')}${kpiCard('Schedule adherence',`${Math.max(0,100-Math.round(state.bookings.filter(b=>b.lateHours>0).length/Math.max(1,state.bookings.length)*100))}%`,'Bookings not forecast late')}${kpiCard('Development workload',`${K.devHours}h`,'Open development tasks')}${kpiCard('Standard execution',state.legs.filter(l=>!l.developmentTaskId).length,'Validation legs')}</div><div class="grid section-grid equal">${section('Category demand & delivery',`<div class="table-wrap"><table><thead><tr><th>Category</th><th>Open</th><th>Upcoming hours</th><th>Late</th><th>Demand index</th></tr></thead><tbody>${cats.map(c=>`<tr><td>${c.category}</td><td>${c.open}</td><td>${c.upcomingHours}</td><td>${c.late}</td><td><div class="heat"><span style="width:${c.utilisation}%"></span></div></td></tr>`).join('')}</tbody></table></div>`)}${section('Highest equipment utilisation',u.equipment.slice().sort((a,b)=>b.pct-a.pct).slice(0,12).map(e=>`<div class="bar-row"><div class="bar-head"><strong>${e.id} · ${esc(e.name)}</strong><span>${e.pct}% · ${Math.round(e.hours)}h</span></div><div class="progress"><span style="width:${e.pct}%"></span></div></div>`).join(''))}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Planned vs actual duration',`<div class="table-wrap"><table><thead><tr><th>Leg</th><th>Method</th><th>Standard</th><th>Actual</th><th>Variance</th></tr></thead><tbody>${completed.map(x=>`<tr><td>${x.l.id}</td><td>${x.m?.id}</td><td>${x.std}h</td><td>${x.actual.toFixed(1)}h</td><td>${x.delta>=0?'+':''}${x.delta.toFixed(1)}h</td></tr>`).join('')}</tbody></table></div>`)}${section('Development queue',devRows())}</div>`}

function renderAdmin(){const d=runDiagnostics(state);return pageHead('Administration / Demo','Persistence, demo controls, scenarios, audit history and deterministic system verification')+`<div class="grid section-grid equal"><section class="card pad"><h2 style="margin-top:0">Demo & Data</h2><div class="detail-grid"><div class="detail"><small>Version</small><strong>LabOS Prototype v${APP_VERSION}</strong></div><div class="detail"><small>Persistence</small><strong>IndexedDB + fallback</strong></div><div class="detail"><small>Demo actor</small><strong>${esc(state.settings.actor)}</strong></div></div><div class="actions"><button class="btn" data-act="export-json">⇩ Export Data</button><button class="btn" data-act="import-json">⇧ Import Data</button><button class="btn danger" data-act="reset-demo">↺ Reset Demo Data</button></div><div class="field"><label>Demo actor</label><input id="actorInput" value="${esc(state.settings.actor)}"></div><button class="btn small" data-act="save-actor">Save actor</button><p class="small muted">Prototype audit history is browser-local and is not a validated electronic-signature or production audit system.</p></section>${section('System Data Integrity',`<div class="callout ${d.overall==='PASS'?'':'danger'}"><strong>${d.overall}</strong> · ${d.pass}/${d.checks.length} automated checks passing.</div><div class="list">${d.checks.map(c=>`<div class="checkline"><span class="${c.ok?'diag-pass':'diag-fail'}">${c.ok?'PASS':'FAIL'}</span><strong>${esc(c.name)}</strong><span class="small muted">${esc(c.detail)}</span></div>`).join('')}</div><div style="padding:12px"><button class="btn primary" data-act="verify">✓ Run System Verification</button></div>`,'Verification uses current canonical browser data')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('What-if scenario',scenarioPanel())}${section('Calibration warning thresholds',`<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Warning days (comma separated)</label><input id="calWarn" value="${state.settings.calibrationWarningDays.join(', ')}"></div><button class="btn small" data-act="save-warnings">Save thresholds</button><p class="small muted">Current visual bands use urgent ≤7d, warning ≤60d. Thresholds are retained for future policy expansion.</p></div>`)}</div>`+
 section('Audit History',`<div class="audit list">${state.audit.slice().reverse().slice(0,40).map(a=>`<div class="list-row"><span>${fmtDate(a.timestamp,true)}</span><strong>${esc(a.actor)}</strong><div><b>${esc(a.action)}</b> · ${esc(a.entity)}<small>${esc(a.previousValue)} ${a.previousValue||a.newValue?'→':''} ${esc(a.newValue)}</small></div></div>`).join('')}</div>`,'Latest 40 session/demo events')}
function scenarioPanel(){return `<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Scenario</label><select id="scenarioType"><option value="equipment_unavailable">Equipment unavailable for 7 days</option><option value="staff_unavailable">Staff unavailable next week</option><option value="add_equipment">Add temporary thermal chamber</option></select></div><div class="field" id="scenarioTargetWrap"><label>Target</label><select id="scenarioTarget">${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="actions"><button class="btn primary" data-act="apply-scenario">Apply & Replan</button>${state.settings.scenario?'<button class="btn" data-act="reset-scenario">Reset Scenario</button>':''}</div>${state.settings.scenario?`<div class="callout warning" style="margin-top:12px"><strong>Active:</strong> ${esc(state.settings.scenario.label||state.settings.scenario.type)}</div>`:''}</div>`}

function wireRoute(){wireEntities(main);for(const b of main.querySelectorAll('[data-act]'))b.addEventListener('click',handleAction);for(const b of main.querySelectorAll('[data-booking]'))b.addEventListener('click',()=>showBooking(b.dataset.booking));if(route==='dashboard'){for(const x of ['dashProgramme','dashCustomer','dashCategory','dashPriority','dashStatus','dashEquipment','dashStaff']){const el=document.getElementById(x);if(el)el.addEventListener('change',async()=>{state.settings.dashboardFilters={programme:document.getElementById('dashProgramme').value,customer:document.getElementById('dashCustomer').value,category:document.getElementById('dashCategory').value,priority:document.getElementById('dashPriority').value,status:document.getElementById('dashStatus').value,equipment:document.getElementById('dashEquipment').value,staff:document.getElementById('dashStaff').value};await persist();render();});}}if(route==='requirements'){for(const x of ['reqStatus','reqCrit','reqFilter'])document.getElementById(x).addEventListener('input',renderReqTable);renderReqTable()}if(route==='duts'){for(const x of ['dutProg','dutStatus','dutFilter'])document.getElementById(x).addEventListener('input',renderDutTable);renderDutTable()}if(route==='programmes'){for(const s of main.querySelectorAll('.priority-change'))s.addEventListener('change',()=>changePriority(s.dataset.id,s.value))}if(route==='admin'){const t=document.getElementById('scenarioType');if(t)t.onchange=updateScenarioTargets;updateScenarioTargets();}}
function wireEntities(root){for(const el of root.querySelectorAll('[data-entity]'))el.addEventListener('click',e=>{e.preventDefault();showEntity(el.dataset.entity,el.dataset.id)})}

async function handleAction(e){const b=e.currentTarget,a=b.dataset.act,id=b.dataset.id;if(a==='replan')return replan();if(a==='scenario')return go('admin');if(a==='reset-scenario')return resetScenario();if(a==='readiness')return showReadiness(id);if(a==='export-json')return exportJSON();if(a==='import-json')return document.getElementById('importFile').click();if(a==='reset-demo')return resetDemo();if(a==='verify')return verifyUI();if(a==='export-req-csv')return exportCSV('requirements');if(a==='export-equipment-csv')return exportCSV('equipment');if(a==='export-cal-csv')return exportCSV('calibrations');if(a==='export-plan-csv')return exportCSV('plan');if(a==='export-kpi-csv')return exportCSV('kpis');if(a==='save-actor'){const v=document.getElementById('actorInput').value.trim()||'Demo Lab Manager';state.audit.push(audit('Demo actor changed','Settings',state.settings.actor,v));state.settings.actor=v;await persist();render();return}if(a==='save-warnings'){const v=document.getElementById('calWarn').value.split(',').map(x=>parseInt(x.trim())).filter(x=>Number.isFinite(x)&&x>0).sort((a,b)=>b-a);if(!v.length)return toast('Enter at least one positive warning threshold.');state.settings.calibrationWarningDays=v;state.audit.push(audit('Calibration warning thresholds changed','Settings','',v.join(',')));await persist();render();return}if(a==='apply-scenario')return applyScenario();if(a==='add-calibration')return addCalibrationModal();if(a==='request-new-test')return requestNewTestModal();if(a==='record-result')return recordResultModal(id);}

async function replan(){const r=scheduleAll(state);state=r.data;lastPlanDiagnostics=r.diagnostics;recomputeRequirementStatuses(state);await persist();render();toast(`Plan recalculated: ${r.diagnostics.moved.length} moved, ${r.diagnostics.unscheduled.length} unscheduled.`)}
async function changePriority(id,val){state=applyPriority(state,id,val);const r=scheduleAll(state);state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`${id} set to ${val}; ${r.diagnostics.moved.length} bookings moved.`)}
function updateScenarioTargets(){const t=document.getElementById('scenarioType'),sel=document.getElementById('scenarioTarget');if(!t||!sel)return;if(t.value==='staff_unavailable')sel.innerHTML=state.staff.map(s=>`<option value="${s.id}">${s.id} · ${esc(s.name)}</option>`).join('');else if(t.value==='add_equipment')sel.innerHTML=[...new Set(state.equipment.map(e=>e.type))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');else sel.innerHTML=state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}
async function applyScenario(){const type=document.getElementById('scenarioType').value,target=document.getElementById('scenarioTarget').value;let sc;if(type==='equipment_unavailable')sc={type,equipmentId:target,start:dayISO(0,8),end:dayISO(7,17),label:`${target} unavailable for 7 days`};else if(type==='staff_unavailable')sc={type,staffId:target,start:dayISO(3,8),end:dayISO(10,17),label:`${state.staff.find(s=>s.id===target)?.name} unavailable next week`};else sc={type,equipmentType:target,label:`Add temporary ${target}`};state.settings.scenario=sc;state.audit.push(audit('Scenario applied','Planning','',sc.label));const r=scheduleAll(state,{scenario:sc});state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`Scenario applied; ${r.diagnostics.moved.length} bookings moved.`)}
async function resetScenario(){state.settings.scenario=null;state.audit.push(audit('Scenario reset','Planning','active','baseline'));const r=scheduleAll(state,{scenario:null});state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast('Scenario reset and baseline schedule recalculated.');}

function showEntity(type,id){if(type==='requirement')return showRequirement(id);if(type==='programme')return showProgramme(id);if(type==='leg')return showLeg(id);if(type==='dut')return showDut(id);if(type==='equipment')return showEquipmentDetail(id);if(type==='method')return showMethod(id);if(type==='staff')return showStaff(id)}
function showRequirement(id){const r=state.requirements.find(x=>x.id===id);if(!r)return;const p=state.programmes.find(x=>x.id===r.programmeId),ls=state.legs.filter(l=>l.requirementIds.includes(r.id)),results=state.results.filter(x=>ls.some(l=>l.id===x.legId));openModal(`<h2>${r.id} · Requirement Traceability</h2><div class="callout"><strong>${esc(r.text)}</strong></div><div class="trace"><div class="trace-step"><small>Source Requirement</small><strong>${r.sourceId}</strong></div><div class="trace-step"><small>Validation Requirement</small><strong>${r.id}</strong></div><div class="trace-step"><small>Verification</small><strong>${r.verificationMethod}</strong></div><div class="trace-step"><small>Test Programme</small><strong>${p?.id} · ${esc(p?.project)}</strong></div><div class="trace-step"><small>Test Legs</small><strong>${ls.map(l=>l.id).join(', ')||'Not covered'}</strong></div><div class="trace-step"><small>Test Method</small><strong>${[...new Set(ls.map(l=>l.methodId))].join(', ')||'—'}</strong></div><div class="trace-step"><small>DUTs</small><strong>${new Set(ls.flatMap(l=>l.dutIds)).size} assigned</strong></div><div class="trace-step"><small>Results / Evidence</small><strong>${results.length} results</strong></div><div class="trace-step"><small>Verification Status</small><strong>${r.status}</strong></div></div><div class="detail-grid"><div class="detail"><small>Criticality</small><strong>${r.criticality}</strong></div><div class="detail"><small>Owner</small><strong>${esc(r.owner)}</strong></div><div class="detail"><small>Coverage</small><strong>${ls.length} test legs</strong></div></div>${results.length?`<div class="table-wrap"><table><thead><tr><th>Result</th><th>DUT</th><th>Parameter</th><th>Value</th><th>Status</th><th>Evidence</th></tr></thead><tbody>${results.slice(0,25).map(x=>`<tr><td>${x.id}</td><td>${x.dutId}</td><td>${x.parameter}</td><td>${x.value} ${x.unit}</td><td>${pill(x.status)}</td><td>${x.evidenceId}</td></tr>`).join('')}</tbody></table></div>`:''}`)}
function showProgramme(id){const p=state.programmes.find(x=>x.id===id),ls=state.legs.filter(l=>l.programmeId===id),req=state.requirements.filter(r=>r.programmeId===id),duts=state.duts.filter(d=>d.programmeId===id),spec=state.specifications?.find(s=>s.programmeId===id);if(!p)return;openModal(`<h2>${p.id} · ${esc(p.project)}</h2><div class="detail-grid"><div class="detail"><small>Customer</small><strong>${esc(p.customer)}</strong></div><div class="detail"><small>Product</small><strong>${esc(p.product)} ${p.productRevision}</strong></div><div class="detail"><small>Priority / Risk</small><strong>${p.priority} · ${p.scheduleRisk}</strong></div><div class="detail"><small>Due</small><strong>${fmtDate(p.dueDate)}</strong></div><div class="detail"><small>Forecast</small><strong>${fmtDate(p.forecastCompletion)}</strong></div><div class="detail"><small>Owner</small><strong>${esc(p.owner)}</strong></div><div class="detail"><small>Specification</small><strong>${spec?`${spec.id} Rev ${spec.revision}`:'—'}</strong></div></div><div class="callout warning"><strong>Demo storyline:</strong> ${esc(p.storyline)}</div><h3>Test programme legs</h3><div class="tree">${ls.map(l=>`<div class="tree-item"><span>${l.sequence}</span><strong>${l.id}</strong><span>${esc(l.name)}</span>${pill(l.status)}</div>`).join('')}</div><h3>Coverage</h3><p class="small">${req.length} requirements · ${duts.length} DUTs · ${req.filter(r=>r.status==='Verified').length} verified · ${req.filter(r=>r.status==='Failed').length} failed.</p>`)}
function showLeg(id){const l=state.legs.find(x=>x.id===id);if(!l)return;const m=state.methods.find(x=>x.id===l.methodId),p=state.programmes.find(x=>x.id===l.programmeId),s=state.staff.find(x=>x.id===l.staffId);openModal(`<h2>${l.id} · ${esc(l.name)}</h2><div class="detail-grid"><div class="detail"><small>Programme</small><strong>${p?.id} · ${esc(p?.project)}</strong></div><div class="detail"><small>Method</small><strong>${m?.id} Rev ${m?.revision}</strong></div><div class="detail"><small>Status</small><strong>${l.status}</strong></div><div class="detail"><small>Planned</small><strong>${fmtDate(l.plannedStart,true)} → ${fmtDate(l.plannedEnd,true)}</strong></div><div class="detail"><small>Equipment</small><strong>${l.equipmentId||'—'}</strong></div><div class="detail"><small>Operator</small><strong>${esc(s?.name||'—')}</strong></div></div><h3>Planning explanation</h3><div class="callout ${l.blockingReason?'warning':''}">${(l.planExplanation?.length?l.planExplanation:[l.blockingReason||'Scheduled without exceptional constraints.']).map(x=>`<div>• ${esc(x)}</div>`).join('')}</div><h3>DUT population</h3><p class="small">${l.dutIds.join(', ')}</p><h3>Requirements covered</h3><p class="small">${l.requirementIds.join(', ')}</p>`)}
function showDut(id){const d=state.duts.find(x=>x.id===id);if(!d)return;const ls=state.legs.filter(l=>l.dutIds.includes(d.id)).sort((a,b)=>a.sequence-b.sequence);openModal(`<h2>${d.id} · DUT Journey</h2><div class="detail-grid"><div class="detail"><small>Serial</small><strong>${d.serialNumber}</strong></div><div class="detail"><small>Programme</small><strong>${d.programmeId}</strong></div><div class="detail"><small>Status</small><strong>${d.status}</strong></div></div><div class="tree">${ls.map((l,i)=>{const r=state.results.find(x=>x.legId===l.id&&x.dutId===d.id);return `<div class="tree-item"><span>${i+1}</span><strong>${l.id}</strong><span>${esc(l.name)}</span>${r?pill(r.status):pill(l.status)}</div>`}).join('')}</div><p class="small muted">Genealogy is derived from canonical leg-to-DUT allocation; failed units remain visible in historical leg membership.</p>`)}
function showEquipmentDetail(id){const e=state.equipment.find(x=>x.id===id);if(!e)return;const cals=state.calibrations.filter(c=>c.equipmentId===id).sort((a,b)=>new Date(b.calibrationDate)-new Date(a.calibrationDate)),bk=state.bookings.filter(b=>b.equipmentId===id).slice(0,10),cs=calibrationStatus(e,state);openModal(`<h2>${e.id} · ${esc(e.name)}</h2><div class="detail-grid"><div class="detail"><small>Asset / Serial</small><strong>${e.assetNumber} · ${e.serialNumber}</strong></div><div class="detail"><small>Status</small><strong>${e.status}</strong></div><div class="detail"><small>Calibration</small><strong>${cs.label}</strong></div><div class="detail"><small>Capability</small><strong>${esc(e.capability)}</strong></div><div class="detail"><small>Location</small><strong>${e.location}</strong></div><div class="detail"><small>Capacity</small><strong>${e.capacity} DUTs</strong></div></div><h3>Calibration history</h3>${cals.slice(0,6).map(c=>`<div class="doc-tile"><div class="doc-icon">PDF</div><div><strong>${c.id} · ${c.certificateNumber}</strong><small>${fmtDate(c.calibrationDate)} → due ${fmtDate(c.dueDate)} · ${esc(c.provider)}</small><div><a class="link small" href="${esc(c.certificatePath)}" target="_blank">Open demo certificate</a></div></div></div>`).join('')}<h3>Bookings</h3><div class="list">${bk.map(b=>`<div class="list-row"><div><strong>${b.legId}</strong><small>${fmtDate(b.start,true)} → ${fmtDate(b.end,true)}</small></div>${pill(b.status)}</div>`).join('')||'<div class="empty">No bookings.</div>'}</div>`)}
function showMethod(id){const m=state.methods.find(x=>x.id===id);if(!m)return;openModal(`<h2>${m.id} Rev ${m.revision} · ${esc(m.name)}</h2><div class="callout">${esc(m.description)}</div><div class="detail-grid"><div class="detail"><small>Category</small><strong>${m.category}</strong></div><div class="detail"><small>Total standard time</small><strong>${m.setupHours+m.executionHours+m.teardownHours+m.analysisHours}h</strong></div><div class="detail"><small>Equipment</small><strong>${m.equipmentType}</strong></div><div class="detail"><small>Skill</small><strong>${m.requiredSkills.join(', ')}</strong></div><div class="detail"><small>DUT capacity</small><strong>${m.dutCapacity}</strong></div><div class="detail"><small>Operation</small><strong>${m.unattended?'Unattended capable':'Continuous staffing'}</strong></div></div><h3>Acceptance</h3><p>${esc(m.acceptance)}</p>`)}
function showStaff(id){const s=state.staff.find(x=>x.id===id);if(!s)return;openModal(`<h2>${esc(s.name)} · ${s.id}</h2><div class="detail-grid"><div class="detail"><small>Role</small><strong>${esc(s.role)}</strong></div><div class="detail"><small>Team</small><strong>${esc(s.team)}</strong></div><div class="detail"><small>Proficiency</small><strong>${s.proficiency}</strong></div></div><h3>Skills</h3><p>${s.skills.join(', ')}</p><h3>Method authorisations</h3><div class="table-wrap"><table><thead><tr><th>Method</th><th>Level</th><th>Expires</th></tr></thead><tbody>${s.qualifications.map(q=>`<tr><td>${q.methodId}</td><td>${q.level}</td><td>${fmtDate(q.expires)}</td></tr>`).join('')}</tbody></table></div>`)}

function showBooking(id){const b=state.bookings.find(x=>x.id===id);if(!b)return;const l=state.legs.find(x=>x.id===b.legId),m=state.methods.find(x=>x.id===l.methodId);const eqOpts=state.equipment.filter(e=>e.type===m.equipmentType).map(e=>`<option value="${e.id}" ${e.id===b.equipmentId?'selected':''}>${e.id} · ${esc(e.name)}</option>`).join('');const staffOpts=state.staff.filter(s=>s.skills.includes(m.requiredSkills[0])).map(s=>`<option value="${s.id}" ${s.id===b.staffId?'selected':''}>${s.id} · ${esc(s.name)}</option>`).join('');openModal(`<h2>${b.id} · Manual Planning</h2><div class="detail-grid"><div class="detail"><small>Programme</small><strong>${b.programmeId}</strong></div><div class="detail"><small>Leg</small><strong>${b.legId}</strong></div><div class="detail"><small>Method</small><strong>${m.id}</strong></div></div><div class="modal-grid"><div class="field"><label>Planned start</label><input id="mvStart" type="datetime-local" value="${b.start.slice(0,16)}"></div><div class="field"><label>Equipment</label><select id="mvEq">${eqOpts}</select></div><div class="field"><label>Technician / engineer</label><select id="mvStaff">${staffOpts}</select></div><div class="field"><label>Freeze booking</label><select id="mvLock"><option value="true" ${b.locked?'selected':''}>Locked</option><option value="false" ${!b.locked?'selected':''}>Unlocked</option></select></div></div><div class="callout"><strong>Hard constraints are enforced.</strong> Incompatible equipment, qualification gaps, double booking, dependency violations and calibration expiry are rejected.</div><div class="actions" style="margin-top:14px"><button id="saveMove" class="btn primary">Save Manual Plan</button></div>`);document.getElementById('saveMove').onclick=async()=>{const start=new Date(document.getElementById('mvStart').value).toISOString(),equipmentId=document.getElementById('mvEq').value,staffId=document.getElementById('mvStaff').value,locked=document.getElementById('mvLock').value==='true';const r=manualMove(state,id,{start,equipmentId,staffId,locked});if(!r.ok){openModal(`<h2>Manual plan rejected</h2><div class="callout danger"><strong>Hard constraint violation</strong>${r.reasons.map(x=>`<div>• ${esc(x)}</div>`).join('')}</div><button class="btn" onclick="location.reload()">Close</button>`);return}state=r.data;await persist();closeModal();render();toast('Manual booking saved and locked state applied.');}}
function showReadiness(id){const l=state.legs.find(x=>x.id===id),m=state.methods.find(x=>x.id===l?.methodId);if(!l||!m)return;const pred=l.predecessorIds.map(id=>state.legs.find(x=>x.id===id)),dev=l.developmentTaskId?state.devTasks.find(d=>d.id===l.developmentTaskId):null,eq=state.equipment.find(e=>e.id===l.equipmentId),st=state.staff.find(s=>s.id===l.staffId),plannedStart=l.plannedStart?new Date(l.plannedStart):null,plannedEnd=l.plannedEnd?new Date(l.plannedEnd):null,cal=eq&&plannedStart?calibrationAt(state,eq.id,plannedStart,{allowScheduled:true}):null,booking=state.bookings.find(b=>b.legId===l.id),resourceValidation=(booking&&plannedStart&&plannedEnd)?validateBooking(state,{legId:l.id,equipmentId:l.equipmentId,staffId:l.staffId,start:l.plannedStart,end:l.plannedEnd,ignoreBookingId:booking.id}):{ok:false,reasons:['No valid planned booking.']};const calOk=!!eq&&(!eq.calibrationRequired||(cal&&plannedEnd&&new Date(cal.dueDate)>=plannedEnd)),plannedReached=!!plannedStart&&plannedStart<=DEMO_NOW;const checks=[['DUTs available',l.dutIds.every(id=>state.duts.find(d=>d.id===id)?.status==='Available'),`${l.dutIds.length} DUTs allocated`],['Predecessors complete',pred.every(p=>p?.status==='Completed'),pred.length?pred.map(p=>`${p.id}: ${p?.status}`).join(', '):'No predecessor'],['Method released',!!m&&(!dev||!!dev.completeDate),dev?`${dev.id}: ${dev.completeDate?'Complete':dev.status}`:`${m.id} Rev ${m.revision}`],['Resources scheduled',!!booking&&!!plannedStart&&!!plannedEnd,`${fmtDate(l.plannedStart,true)} → ${fmtDate(l.plannedEnd,true)}`],['Planned start reached',plannedReached,plannedStart?`Demo clock ${fmtDate(DEMO_NOW,true)} · planned ${fmtDate(plannedStart,true)}`:'Not planned'],['Equipment / staff constraints valid',resourceValidation.ok,resourceValidation.ok?`${eq?.id||'—'} · ${st?.name||'—'}`:resourceValidation.reasons.join(' ')],['Calibration valid through test',calOk,eq?(eq.calibrationRequired?(cal?`${cal.id}${cal.result==='Scheduled'?' (scheduled before use)':''} · due ${fmtDate(cal.dueDate)}`:'No effective calibration at planned start'):'Calibration not required'):'No equipment'],['Operator qualified',!!st&&st.qualifications.some(q=>q.methodId===m.id&&['Independent','Reviewer','Trainer/Expert'].includes(q.level)&&new Date(q.expires)>plannedStart),st?.name||'No operator']];const ok=checks.every(x=>x[1]);openModal(`<h2>${l.id} · Start Readiness</h2><div class="callout ${ok?'':'danger'}"><strong>${ok?'READY':'BLOCKED'}</strong> · ${ok?'All mandatory pre-start checks pass.':'One or more hard prerequisites are not satisfied.'}</div><div class="list">${checks.map(c=>`<div class="checkline"><span class="${c[1]?'diag-pass':'diag-fail'}">${c[1]?'PASS':'FAIL'}</span><strong>${c[0]}</strong><span class="small muted">${esc(c[2])}</span></div>`).join('')}</div>${ok&&l.status!=='Completed'?`<button id="startTestBtn" class="btn primary">Start Test</button>`:''}`);const btn=document.getElementById('startTestBtn');if(btn)btn.onclick=async()=>{l.status='In Progress';l.actualStart=new Date().toISOString();state.audit.push(audit('Test started',l.id,'Planned','In Progress'));await persist();closeModal();render();toast(`${l.id} started.`)}}

function recordResultModal(id){const l=state.legs.find(x=>x.id===id);if(!l)return;const existing=state.results.filter(r=>r.legId===id),covered=new Set(existing.map(r=>r.dutId)),completeReady=l.dutIds.every(d=>covered.has(d));openModal(`<h2>${l.id} · Results & Evidence</h2><div class="callout"><strong>Deterministic acceptance:</strong> numeric and categorical outcomes are calculated from the entered criterion; the PASS/FAIL field is not editable.</div><div class="modal-grid"><div class="field"><label>DUT</label><select id="resDut">${l.dutIds.map(d=>`<option value="${d}">${d}</option>`).join('')}</select></div><div class="field"><label>Result type</label><select id="resType"><option value="numeric">Numeric</option><option value="categorical">Categorical</option><option value="text">Text / observation</option></select></div><div class="field"><label>Parameter</label><input id="resParam" value="Measured Parameter"></div><div class="field"><label>Unit</label><input id="resUnit" value="V"></div><div class="field numeric-res"><label>Value</label><input id="resValue" type="number" step="any" value="10"></div><div class="field numeric-res"><label>Lower limit</label><input id="resLow" type="number" step="any" value="8"></div><div class="field numeric-res"><label>Upper limit</label><input id="resHigh" type="number" step="any" value="14"></div><div class="field cat-res hidden"><label>Actual category</label><input id="resCatActual" value="PASS CONDITION"></div><div class="field cat-res hidden"><label>Required category</label><input id="resCatExpected" value="PASS CONDITION"></div><div class="field text-res hidden"><label>Observation</label><textarea id="resText">Observation recorded.</textarea></div><div class="field"><label>Evidence attachment</label><input id="resFile" type="file"></div><div class="field"><label>Comments</label><textarea id="resComments"></textarea></div></div><div class="actions"><button id="saveResult" class="btn primary">Save Result</button><button id="completeLeg" class="btn" ${completeReady?'':'disabled'}>Complete Test</button></div><h3>Recorded results</h3><div class="table-wrap"><table><thead><tr><th>DUT</th><th>Parameter</th><th>Value</th><th>Status</th><th>Evidence</th></tr></thead><tbody>${existing.map(r=>`<tr><td>${r.dutId}</td><td>${esc(r.parameter)}</td><td>${esc(r.value)} ${esc(r.unit||'')}</td><td>${pill(r.status)}</td><td>${r.evidenceId||'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No results recorded yet.</td></tr>'}</tbody></table></div>`);const type=document.getElementById('resType');const toggle=()=>{for(const x of document.querySelectorAll('.numeric-res'))x.classList.toggle('hidden',type.value!=='numeric');for(const x of document.querySelectorAll('.cat-res'))x.classList.toggle('hidden',type.value!=='categorical');for(const x of document.querySelectorAll('.text-res'))x.classList.toggle('hidden',type.value!=='text')};type.onchange=toggle;toggle();document.getElementById('saveResult').onclick=async()=>{const dutId=document.getElementById('resDut').value,resultType=type.value,param=document.getElementById('resParam').value.trim()||'Result',unit=document.getElementById('resUnit').value.trim(),comments=document.getElementById('resComments').value;let value,lowerLimit=null,upperLimit=null,status;if(resultType==='numeric'){value=Number(document.getElementById('resValue').value);lowerLimit=document.getElementById('resLow').value===''?null:Number(document.getElementById('resLow').value);upperLimit=document.getElementById('resHigh').value===''?null:Number(document.getElementById('resHigh').value);if(!Number.isFinite(value))return toast('Enter a numeric result value.');status=((lowerLimit!=null&&value<lowerLimit)||(upperLimit!=null&&value>upperLimit))?'FAIL':'PASS';}else if(resultType==='categorical'){value=document.getElementById('resCatActual').value;const expected=document.getElementById('resCatExpected').value;status=value.trim().toLowerCase()===expected.trim().toLowerCase()?'PASS':'FAIL';}else{value=document.getElementById('resText').value;status='RECORDED';}const file=document.getElementById('resFile').files[0];let evidenceData=null;if(file)evidenceData=await fileToDataURL(file);const rid=`RES-${String(state.results.length+1).padStart(4,'0')}`,evidenceId=evidenceData?`EVID-${rid}`:null;state.results.push({id:rid,legId:id,dutId,parameter:param,value,unit,lowerLimit,upperLimit,resultType,status,timestamp:new Date().toISOString(),evidenceId,evidenceData,comments});const dut=state.duts.find(d=>d.id===dutId);if(status==='FAIL')dut.status='Failed';state.audit.push(audit('Test result recorded',rid,'',`${status} · ${dutId}`));recomputeRequirementStatuses(state);await persist();recordResultModal(id);toast(`${rid} saved as ${status}.`)};document.getElementById('completeLeg').onclick=async()=>{const current=state.results.filter(r=>r.legId===id),missing=l.dutIds.filter(d=>!current.some(r=>r.dutId===d));if(missing.length)return toast(`Cannot complete: mandatory result missing for ${missing.length} DUT(s).`);l.status='Completed';l.actualEnd=new Date().toISOString();for(const dutId of l.dutIds){const rs=current.filter(r=>r.dutId===dutId),st=rs.some(r=>r.status==='FAIL')?'FAIL':'PASS',dut=state.duts.find(d=>d.id===dutId);dut.history.push({legId:l.id,status:st,date:l.actualEnd});if(st==='FAIL')dut.status='Failed';}const b=state.bookings.find(b=>b.legId===l.id);if(b)b.status='Completed';state.audit.push(audit('Test completed',l.id,'In Progress','Completed'));recomputeRequirementStatuses(state);await persist();closeModal();render();toast(`${l.id} completed; requirement status recalculated.`)}}
function requestNewTestModal(){const types=[...new Set(state.equipment.map(e=>e.type))].sort();openModal(`<h2>Request New / Non-existing Test</h2><p class="small muted">Creating a non-library test automatically creates a method-development prerequisite and an open test request.</p><div class="modal-grid"><div class="field"><label>Programme</label><select id="ntProg">${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select></div><div class="field"><label>Test name</label><input id="ntName" value="Custom validation method"></div><div class="field"><label>Category</label><select id="ntCat">${['Electrical','Environmental','Mechanical','Reliability','EMC','Functional','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Required equipment type</label><select id="ntEqType">${types.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Required skill</label><select id="ntSkill">${[...new Set(state.staff.flatMap(s=>s.skills))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Estimated execution hours</label><input id="ntHours" type="number" min="1" value="16"></div><div class="field"><label>Development elapsed days</label><input id="ntDevDays" type="number" min="1" value="7"></div></div><button id="createNewTest" class="btn primary">Create Demand & Development Task</button>`);document.getElementById('createNewTest').onclick=async()=>{const pid=document.getElementById('ntProg').value,name=document.getElementById('ntName').value.trim()||'Custom validation method',cat=document.getElementById('ntCat').value,eqType=document.getElementById('ntEqType').value,skill=document.getElementById('ntSkill').value,hours=Math.max(1,Number(document.getElementById('ntHours').value)||16),devDays=Math.max(1,Number(document.getElementById('ntDevDays').value)||7);const methodId=`NEW-${String(state.methods.filter(m=>m.id.startsWith('NEW-')).length+1).padStart(3,'0')}`,devId=`DEV-${String(state.devTasks.length+1).padStart(3,'0')}`,legId=`LEG-${String(state.legs.length+1).padStart(3,'0')}`,trId=`TR-${String((state.testRequests||[]).length+1).padStart(3,'0')}`,prog=state.programmes.find(p=>p.id===pid),existing=state.legs.filter(l=>l.programmeId===pid).sort((a,b)=>a.sequence-b.sequence),pred=existing.at(-1),req=state.requirements.find(r=>r.programmeId===pid&&r.status==='Not Covered')||state.requirements.find(r=>r.programmeId===pid);state.methods.push({id:methodId,name,category:cat,revision:'DRAFT',description:'New method under development',executionHours:hours,setupHours:4,teardownHours:2,analysisHours:4,equipmentType:eqType,requiredSkills:[skill],staffing:1,unattended:true,continuousStaffing:false,dutCapacity:8,defaultParameters:{},acceptance:'To be released during method development',active:false,useCount:0,avgActualFactor:1});const dev={id:devId,programmeId:pid,legId,name:`Develop ${name}`,status:'Queued',estimatedEngineeringHours:40,estimatedTechnicianHours:16,elapsedDays:devDays,requiredSkills:[skill],startDate:dayISO(1,8),dueDate:dayISO(1+devDays,17),completeDate:null};state.devTasks.push(dev);const leg={id:legId,programmeId:pid,name,sequence:(pred?.sequence||0)+1,methodId,dutIds:state.duts.filter(d=>d.programmeId===pid&&d.status!=='Failed').slice(0,8).map(d=>d.id),requirementIds:req?[req.id]:[],predecessorIds:pred?[pred.id]:[],parallelGroup:null,status:'Draft',requestedDate:new Date().toISOString(),dueDate:prog.dueDate,plannedStart:null,plannedEnd:null,actualStart:null,actualEnd:null,equipmentId:null,staffId:null,locked:false,blockingReason:null,developmentTaskId:devId,planExplanation:[],priority:prog.priority};state.legs.push(leg);(state.testRequests||(state.testRequests=[])).push({id:trId,programmeId:pid,legId,requestedBy:state.settings.actor,requestedDate:new Date().toISOString(),requiredCompletion:prog.dueDate,priority:prog.priority,status:'Open',methodId});if(req){req.testLegIds=[...(req.testLegIds||[]),legId];}state.audit.push(audit('New test request created',trId,'',`${methodId} + ${devId}`));const r=scheduleAll(state);state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();closeModal();render();toast(`${trId} created with automatic development task ${devId}.`);}}
function addCalibrationModal(){openModal(`<h2>Add Calibration Record</h2><div class="modal-grid"><div class="field"><label>Equipment</label><select id="calEq">${state.equipment.filter(e=>e.calibrationRequired).map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Calibration date</label><input id="calDate" type="date" value="${DEMO_NOW.toISOString().slice(0,10)}"></div><div class="field"><label>Due date</label><input id="calDue" type="date" value="${dayISO(365).slice(0,10)}"></div><div class="field"><label>Certificate number</label><input id="calCert" value="CERT-DEMO-${Date.now().toString().slice(-5)}"></div><div class="field"><label>Provider</label><input id="calProv" value="Internal Metrology"></div><div class="field"><label>Certificate attachment</label><input id="calFile" type="file" accept="application/pdf,image/*"></div></div><button id="saveCal" class="btn primary">Save Calibration</button>`);document.getElementById('saveCal').onclick=async()=>{const eqId=document.getElementById('calEq').value,date=document.getElementById('calDate').value,due=document.getElementById('calDue').value;if(!date||!due||new Date(due)<=new Date(date))return toast('Due date must be after calibration date.');const file=document.getElementById('calFile').files[0];let attachmentData=null;if(file)attachmentData=await fileToDataURL(file);const c={id:`CAL-${String(state.calibrations.length+1).padStart(3,'0')}`,equipmentId:eqId,calibrationDate:new Date(date+'T09:00:00Z').toISOString(),dueDate:new Date(due+'T17:00:00Z').toISOString(),certificateNumber:document.getElementById('calCert').value,provider:document.getElementById('calProv').value,result:'Pass',comments:'User-added demo calibration',certificatePath:attachmentData||'TC-04-certificate.pdf',uncertainty:'See attachment',asFound:'Within tolerance',asLeft:'Within tolerance',measurementTable:[]};state.calibrations.push(c);const eq=state.equipment.find(e=>e.id===eqId);eq.calibrationDue=c.dueDate;eq.currentCalibrationId=c.id;state.audit.push(audit('Calibration added',eqId,'',c.id));await persist();closeModal();render();toast('Calibration record saved locally.');}}
function fileToDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}

function search(q){q=q.trim().toLowerCase();if(q.length<2){searchOverlay.classList.add('hidden');return}const hits=[];const add=(type,id,label,sub)=>hits.push({type,id,label,sub});for(const r of state.requirements)if(`${r.id} ${r.sourceId} ${r.text}`.toLowerCase().includes(q))add('requirement',r.id,r.id,r.text);for(const p of state.programmes)if(`${p.id} ${p.project} ${p.product} ${p.customer}`.toLowerCase().includes(q))add('programme',p.id,`${p.id} · ${p.project}`,p.product);for(const d of state.duts)if(`${d.id} ${d.serialNumber}`.toLowerCase().includes(q))add('dut',d.id,d.id,d.serialNumber);for(const e of state.equipment)if(`${e.id} ${e.assetNumber} ${e.serialNumber} ${e.name}`.toLowerCase().includes(q))add('equipment',e.id,`${e.id} · ${e.name}`,`${e.assetNumber} · ${e.serialNumber}`);for(const m of state.methods)if(`${m.id} ${m.name}`.toLowerCase().includes(q))add('method',m.id,`${m.id} · ${m.name}`,m.category);for(const s of state.staff)if(`${s.id} ${s.name} ${s.role}`.toLowerCase().includes(q))add('staff',s.id,`${s.name} · ${s.id}`,s.role);for(const c of state.calibrations)if(`${c.id} ${c.certificateNumber}`.toLowerCase().includes(q))add('equipment',c.equipmentId,`${c.certificateNumber}`,`${c.id} · ${c.equipmentId}`);searchOverlay.innerHTML=hits.slice(0,16).map(h=>`<div class="search-hit" data-entity="${h.type}" data-id="${h.id}"><small>${h.type}</small><strong>${esc(h.label)}</strong><div class="small muted">${esc(h.sub).slice(0,100)}</div></div>`).join('')||'<div class="empty">No matches.</div>';searchOverlay.classList.remove('hidden');wireEntities(searchOverlay);for(const x of searchOverlay.querySelectorAll('[data-entity]'))x.addEventListener('click',()=>searchOverlay.classList.add('hidden'))}

function download(name,content,type='application/octet-stream'){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportJSON(){download(`LabOS-${APP_VERSION}-data.json`,JSON.stringify(state,null,2),'application/json');state.audit.push(audit('Data exported','System','','JSON'));persist();toast('Full system data exported to JSON.');}
async function importJSON(e){const f=e.target.files[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(!obj.meta||!Array.isArray(obj.programmes)||!Array.isArray(obj.legs))throw new Error('Not a LabOS data export');state=obj;state.meta.version=APP_VERSION;addCompletedBookings(state);recomputeRequirementStatuses(state);state.audit=state.audit||[];state.audit.push(audit('Data imported','System',f.name,'Loaded'));await persist();render();toast('JSON data imported successfully.');}catch(err){toast(`Import rejected: ${err.message}`)}e.target.value=''}
async function resetDemo(){if(!confirm('Reset all browser-local changes and restore the deterministic demo dataset?'))return;await clearState();state=createDemoData();addCompletedBookings(state);const r=scheduleAll(state,{recordAudit:false});state=r.data;lastPlanDiagnostics=r.diagnostics;recomputeRequirementStatuses(state);await persist();render();toast('Deterministic demo data restored.');}
function exportCSV(kind){let rows;if(kind==='requirements')rows=state.requirements.map(r=>({id:r.id,source:r.sourceId,programme:r.programmeId,criticality:r.criticality,status:r.status,text:r.text,testLegs:r.testLegIds?.join('|')||''}));else if(kind==='equipment')rows=state.equipment.map(e=>({id:e.id,asset:e.assetNumber,name:e.name,type:e.type,status:e.status,location:e.location,calibrationDue:e.calibrationDue}));else if(kind==='plan')rows=state.bookings.map(b=>({booking:b.id,programme:b.programmeId,leg:b.legId,method:b.methodId,start:b.start,end:b.end,equipment:b.equipmentId,staff:b.staffId,priority:b.priority,lateHours:b.lateHours,locked:b.locked}));else if(kind==='kpis'){const x=kpis(state);rows=Object.entries(x).map(([metric,value])=>({metric,value}));}else rows=state.calibrations.map(c=>({id:c.id,equipment:c.equipmentId,date:c.calibrationDate,due:c.dueDate,certificate:c.certificateNumber,provider:c.provider,result:c.result}));const cols=Object.keys(rows[0]||{}),csv=[cols.join(','),...rows.map(r=>cols.map(c=>`"${String(r[c]??'').replaceAll('"','""')}"`).join(','))].join('\n');download(`LabOS-${kind}.csv`,csv,'text/csv');toast(`${kind} CSV exported.`)}
function verifyUI(){const d=runDiagnostics(state);openModal(`<h2>System Verification · ${d.overall}</h2><div class="callout ${d.overall==='PASS'?'':'danger'}"><strong>${d.pass}/${d.checks.length} checks passed</strong></div><div class="list">${d.checks.map(c=>`<div class="checkline"><span class="${c.ok?'diag-pass':'diag-fail'}">${c.ok?'PASS':'FAIL'}</span><strong>${esc(c.name)}</strong><span class="small muted">${esc(c.detail)}</span></div>`).join('')}</div>`)}

init().catch(err=>{console.error(err);main.innerHTML=`<div class="callout danger"><strong>Application failed to initialise.</strong><div>${esc(err.message)}</div></div>`});
